    "Privacy notice and your rights": "Privacy notice and your rights",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.": "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.",
    "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.": "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.",
