    "Clearing this app’s local data creates a different identity. Your signing key stays nonextractable on this device.": "Clearing this app’s local data creates a different identity. Your signing key stays nonextractable on this device.",
    "Vumiro account · sync and recovery": "Vumiro account · sync and recovery",
    "An optional account restores your profile, friends, blocks and stream preferences on another device. Your signing identity is encrypted in the app before backup; unlock it with your backup password or identity recovery code to restore the same contact identity.": "An optional account restores your profile, friends, blocks and stream preferences on another device. Your signing identity is encrypted in the app before backup; unlock it with your backup password or identity recovery code to restore the same contact identity.",
    "Not signed in. Your existing local data stays on this device.": "Not signed in. Your existing local data stays on this device.",
    "Email": "Email",
