    "Confirm your password before this security change": "Confirm your password before this security change",
    "Restore account data to this device": "Restore account data to this device",
    "Back up this device to your account": "Back up this device to your account",
    "Revoke a lost device to block its saved account session from syncing.": "Revoke a lost device to block its saved account session from syncing.",
    "Your email and password are handled by the authentication provider. Your profile, friends, blocks, and settings are synced through the Vumiro account service.": "Your email and password are handled by the authentication provider. Your profile, friends, blocks, and settings are synced through the Vumiro account service.",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email, profile, friends' public contact details and local nicknames, blocks, device activity and preferences to sign you in and restore your account across devices. Optional bios, backgrounds and manually entered provider links are exchanged directly with connected friends and included in your own profile backup. Friends' cached profile-card details are excluded from your backup. Links are not verified integrations.": "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email, profile, friends' public contact details and local nicknames, blocks, device activity and preferences to sign you in and restore your account across devices. Optional bios, backgrounds and manually entered provider links are exchanged directly with connected friends and included in your own profile backup. Friends' cached profile-card details are excluded from your backup. Links are not verified integrations.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing-identity backup is encrypted in the app; other synced fields are readable by authorized operators and providers. Screens, voice, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing-identity backup is encrypted in the app; other synced fields are readable by authorized operators and providers. Screens, voice, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.",
    "You can export account data, correct your profile, sign out and delete your account here. Deletion removes synced data and requests deletion of the authentication identity. Failed provider deletions stay pending for automatic retry until completed. Local device data and signing keys remain on this device. The separate connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry, independently of account deletion. Hourly hashed IP allocation counters expire after their hourly window. There is no in-app directory-record deletion control; contact the operator about those records. Never send passwords, verification codes, recovery codes or private keys to support.": "You can export account data, correct your profile, sign out and delete your account here. Deletion removes synced data and requests deletion of the authentication identity. Failed provider deletions stay pending for automatic retry until completed. Local device data and signing keys remain on this device. The separate connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry, independently of account deletion. Hourly hashed IP allocation counters expire after their hourly window. There is no in-app directory-record deletion control; contact the operator about those records. Never send passwords, verification codes, recovery codes or private keys to support.",
    "The full notice, version 2026-11-03, included with Vumiro explains retention, provider processing and your rights. The account service does not provide end-to-end encryption for profile and contact fields.": "The full notice, version 2026-11-03, included with Vumiro explains retention, provider processing and your rights. The account service does not provide end-to-end encryption for profile and contact fields.",
