    "Vumiro — Sakura idle": "Vumiro — Sakura idle",
    "Fourteen small sakura petals descend slowly with gentle drift and rotation. Transparent, seamless 28-second vector loop. Reduced-motion preferences hide the effect.": "Fourteen small sakura petals descend slowly with gentle drift and rotation. Transparent, seamless 28-second vector loop. Reduced-motion preferences hide the effect.",
    "Vumiro — Blade reveal": "Vumiro — Blade reveal",
    "A curved red blade cut traces the actual opening in the V and reveals the mark in the center. The V glides left as the outlined Vumiro wordmark reveals and glides right. A brief camera push, roll and damped recoil emphasize the cut. The completed logo holds, then fades out. Duration 4.8 seconds.": "A curved red blade cut traces the actual opening in the V and reveals the mark in the center. The V glides left as the outlined Vumiro wordmark reveals and glides right. A brief camera push, roll and damped recoil emphasize the cut. The completed logo holds, then fades out. Duration 4.8 seconds.",
