    "Your space, together": "Tu espacio, juntos",
    "Welcome back.": "Bienvenido de nuevo.",
    "Sign in to restore your profile and friends.": "Inicie sesión para restaurar su perfil y sus amigos.",
    "Account access": "Acceso a la cuenta",
    "Email address": "Dirección de correo electrónico",
    "Password": "Contraseña",
    "Enter your password": "Ingrese su contraseña",
    "Show password": "Mostrar contraseña",
    "Use at least 12 characters.": "Utilice al menos 12 caracteres.",
    "Privacy notice and your rights": "Aviso de privacidad y sus derechos",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.": "Emanuel Queiroz (snoopeh) opera el servicio de cuenta opcional de Vumiro. Solicitudes de privacidad y reportes de incidencias: snopeeh@gmail.com. Usamos su correo electrónico para iniciar sesión y restaurar su perfil, amigos, bloqueos, dispositivos y preferencias. Las biografías opcionales, los fondos de perfil y los enlaces de proveedores ingresados ​​manualmente se comparten directamente con amigos conectados y se incluyen en la copia de seguridad de su propia cuenta. Los enlaces no son integraciones verificadas. Google o Microsoft comparten su correo electrónico y su perfil básico solo cuando elige una opción de inicio de sesión habilitada.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth está alojado en São Paulo, Brasil; El almacenamiento de la cuenta Cloudflare D1 se encuentra en el este de América del Norte; Brevo entrega correos electrónicos de cuentas utilizando una infraestructura alojada en la UE. Los proveedores también procesan información operativa a nivel internacional. Su identidad de firma está cifrada en la aplicación antes de la copia de seguridad. Otros campos sincronizados son legibles por operadores y proveedores autorizados. Las pantallas, el audio, el chat, las contraseñas de las salas, las claves privadas sin procesar y los códigos de recuperación no se cargan en el servicio de cuenta.",
    "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.": "Puede exportar, corregir o eliminar datos de la cuenta en la configuración; Los datos del dispositivo local permanecen. Por otra parte, el directorio de conexión conserva las asignaciones de reproducción de migración y etiqueta de identidad a amigo sin caducidad automática; eliminar una cuenta de Supabase no las borra. Los contadores de asignación de IP con hash por hora caducan después de su ventana horaria. Las eliminaciones de identidad de autenticación fallidas permanecen pendientes de reintento hasta que se completen. El aviso completo, versión 2026-11-03, se envía como PRIVACY.md (Windows) o licenses/PRIVACY.md (Linux) y explica la retención, el procesamiento de correo electrónico y sus derechos. Nunca envíe contraseñas o secretos de recuperación al soporte.",
    "I reviewed the privacy notice": "Revisé el aviso de privacidad",
