    "Connection service": "Servicio de conexión",
    "The service exchanges online names, requests and room availability. Your photo, screen and voice travel directly between peers.": "El servicio intercambia nombres, solicitudes y disponibilidad de salas en línea. Su foto, pantalla y voz viajan directamente entre pares.",
    "Service URL": "URL del servicio",
    "Save connection": "Guardar conexión",
    "Blocked identities": "Identidades bloqueadas",
    "Blocked identities cannot find you or send requests while this profile is connected. Unblocking does not add them as friends.": "Las identidades bloqueadas no pueden encontrarlo ni enviar solicitudes mientras este perfil está conectado. El desbloqueo no los agrega como amigos.",
    "App updates": "Actualizaciones de aplicaciones",
    "Vumiro desktop client": "Cliente de escritorio Vumiro",
    "Checking for updates…": "Comprobando actualizaciones…",
    "Check for updates": "Buscar actualizaciones",
    "Update now": "Actualizar ahora",
    "Installing restarts Vumiro and preserves your local profile and friends. Leave your room before installing.": "La instalación reinicia Vumiro y conserva su perfil local y sus amigos. Sal de tu sala antes de instalar.",
    "Stream diagnostics": "Diagnóstico de transmisión",
    "If a share fails, export the last 24 hours of technical events. Windows includes the previous session status. History has a size limit and contains no audio, video, chats, credentials or peer addresses.": "Si un recurso compartido falla, exporte las últimas 24 horas de eventos técnicos. Windows incluye el estado de la sesión anterior. El historial tiene un límite de tamaño y no contiene audio, vídeo, chats, credenciales ni direcciones de pares.",
    "Export diagnostic logs": "Exportar registros de diagnóstico",
    "QA notification tests": "Pruebas de notificación de control de calidad",
    "Preview call, friend request, and room alerts locally. These previews do not send requests or open rooms.": "Vista previa de llamadas, solicitudes de amistad y alertas de sala localmente. Estas vistas previas no envían solicitudes ni abren salas.",
    "Test incoming call": "Prueba de llamada entrante",
    "Test friend request": "Prueba de solicitud de amistad",
    "Test room activity": "Probar alerta de actividad de sala",
