    "No new activity yet.": "Aún no hay nueva actividad.",
    "Recent notifications": "Notificaciones recientes",
    "Join an online friend’s room. Friends rooms use mutual contacts; private rooms require a password.": "Únase a la sala de un amigo en línea. Las salas de amigos utilizan contactos mutuos; Las salas privadas requieren una contraseña.",
    "No friends’ rooms are open right now.": "No hay salas de amigos abiertas en este momento.",
