    "Restoring your room connection…": "Restaurando la conexión de su sala…",
    "Connecting securely. Your microphone and screen stay off until you choose to share.": "Conectando de forma segura. El micrófono y la pantalla permanecen apagados hasta que elijas compartir.",
    "This is taking longer than expected. You can retry or return to your friends.": "Esto está tardando más de lo esperado. Puedes volver a intentarlo o volver con tus amigos.",
    "Could not save all changes. Your unsaved changes are still here.": "No se pudieron guardar todos los cambios. Los cambios no guardados todavía están aquí.",
    "Some settings changed while saving. Review your changes before leaving.": "Algunas configuraciones cambiaron al guardar. Revise sus cambios antes de partir.",
    "Save your changes?": "¿Guardar sus cambios?",
    "You changed your settings. Save or discard your changes before leaving.": "Cambiaste tu configuración. Guarde o descarte sus cambios antes de salir.",
    "Keep editing": "Seguir editando",
    "Discard changes": "Descartar cambios",
    "Save changes": "Guardar cambios",
    "Skip intro": "Saltar introducción",
    "Try again": "Inténtalo de nuevo",
    "Connection interrupted. Rejoining in {seconds} seconds…": "Conexión interrumpida. Volver a unirme en {seconds} segundos…",
    "Waiting for the room owner. Trying again in {seconds} seconds…": "Esperando al dueño de la sala. Intentando de nuevo en {seconds} segundos…",
    "An account restores your profile, friends, blocks, stream preferences, and an encrypted signing identity on another device. Enabling recovery for an older profile changes its contact code; updated friends verify the signed transition automatically while older app versions may require a new friend acceptance.": "Una cuenta restaura su perfil, amigos, bloqueos, preferencias de transmisión y una identidad de firma cifrada en otro dispositivo. Al habilitar la recuperación de un perfil anterior se cambia su código de contacto; Los amigos actualizados verifican la transición firmada automáticamente, mientras que las versiones anteriores de la aplicación pueden requerir la aceptación de un nuevo amigo.",
    "Profile backed up. High-resolution covers still stay on this device and share directly with updated friends; private cover backup is not enabled on the service yet.": "Perfil respaldado. Las portadas de alta resolución aún permanecen en este dispositivo y se comparten directamente con amigos actualizados; La copia de seguridad de cobertura privada aún no está habilitada en el servicio.",
    "This device is backed up. Only the finished cover is backed up; the editable original stays on this device. Changes will sync automatically while Vumiro is open.": "Este dispositivo tiene una copia de seguridad. Sólo se respalda la cubierta terminada; el original editable permanece en este dispositivo. Los cambios se sincronizarán automáticamente mientras Vumiro esté abierto.",
    "Identity recovery is enabled. Save the recovery code before closing this panel. Your contact code changed; older friends may need to accept a new request.": "La recuperación de identidad está habilitada. Guarde el código de recuperación antes de cerrar este panel. Su código de contacto cambió; Es posible que los amigos mayores deban aceptar una nueva solicitud.",
    "0% mutes; 100% is original volume; up to 400% boosts quiet audio (may distort)": "0% silenciados; 100% es el volumen original; hasta un 400 % aumenta el audio silencioso (puede distorsionar)",
    "Friend request resolved; the blocked identity was not added.": "Solicitud de amistad resuelta; la identidad bloqueada no fue agregada.",
    "Online. Named tags need the updated Vumiro service; your existing tag and contact code still work.": "En línea. Las etiquetas con nombre necesitan el servicio Vumiro actualizado; su etiqueta y código de contacto existentes aún funcionan.",
    "Your username is saved. Shared usernames need the updated Vumiro service; use your existing tag or contact code for now.": "Su nombre de usuario está guardado. Los nombres de usuario compartidos necesitan el servicio Vumiro actualizado; use su etiqueta existente o código de contacto por ahora.",
    "Service offline. Reconnecting automatically; you can also use Reconnect.": "Servicio fuera de línea. Reconectarse automáticamente; También puedes usar Reconectar.",
    "display-capture; microphone; speaker-selection; autoplay; fullscreen": "captura de pantalla; micrófono; selección de oradores; reproducción automática; pantalla completa",
    "{p0}’s code is valid. Reconnect to send a request; they must also be online.": "El código de {p0} es válido. Vuelva a conectarse para enviar una solicitud; también deben estar en línea.\nEl código de",
    "’s code is valid. Reconnect to send a request; they must also be online.": "es válido. Vuelva a conectarse para enviar una solicitud; también deben estar en línea.",
    "On Windows, visual alerts flash the taskbar; Notification Center popups are unavailable in this build.": "En Windows, las alertas visuales parpadean en la barra de tareas; Las ventanas emergentes del Centro de notificaciones no están disponibles en esta versión.",
    "Audio boost unavailable; playing at up to 100%: {p0}": "Aumento de audio no disponible; jugando hasta al 100%: {p0}",
    "Audio boost unavailable; playing at up to 100%:": "Aumento de audio no disponible; jugando hasta al 100%:",
