    "Vumiro — Sakura idle": "Vumiro - Sakura inactiva",
    "Fourteen small sakura petals descend slowly with gentle drift and rotation. Transparent, seamless 28-second vector loop. Reduced-motion preferences hide the effect.": "Catorce pequeños pétalos de sakura descienden lentamente con una suave deriva y rotación. Bucle vectorial transparente y sin interrupciones de 28 segundos. Las preferencias de movimiento reducido ocultan el efecto.",
    "Vumiro — Blade reveal": "Vumiro - Revelación de la espada",
    "A curved red blade cut traces the actual opening in the V and reveals the mark in the center. The V glides left as the outlined Vumiro wordmark reveals and glides right. A brief camera push, roll and damped recoil emphasize the cut. The completed logo holds, then fades out. Duration 4.8 seconds.": "Un corte curvo de hoja roja traza la abertura real en la V y revela la marca en el centro. La V se desliza hacia la izquierda mientras se revela la marca denominativa Vumiro delineada y se desliza hacia la derecha. Un breve empujón, giro y retroceso amortiguado de la cámara enfatizan el corte. El logotipo completo se mantiene y luego se desvanece. Duración 4,8 segundos.",
    "Up to 720p": "Hasta 720p",
