    "A sample notification will appear in 3 seconds. Minimize Vumiro to test the desktop popup.": "Aparecerá una notificación de prueba en 3 segundos. Minimiza Vumiro para probar la ventana del escritorio.",
    "This is your desktop notification preview.": "Esta es la vista previa de tu notificación de escritorio.",
