    "The Vumiro intro plays once when you fully quit and open the app. Restoring it from the tray or reloading the interface keeps your place.": "La intro de Vumiro se reproduce una vez al cerrar por completo y volver a abrir la aplicación. Al restaurarla desde la bandeja o recargar la interfaz, puedes seguir donde estabas.",
