    "Your chat, your storage": "Tu chat, tu almacenamiento",
    "Signed room text and attachment descriptions are saved on this device. Original attachment files are not archived yet. History belongs to your signing identity and the original room; the account backup does not include chat history.": "Los mensajes de texto firmados de las salas y las descripciones de los archivos adjuntos se guardan en este dispositivo. Los archivos adjuntos originales aún no se archivan. El historial pertenece a tu identidad de firma y a la sala original; la copia de seguridad de la cuenta no incluye el historial de chat.",
    "Store new chat history": "Guardar el nuevo historial de chat",
