    "Create a persistent server record with a #general text channel. Shared channel conversations, memberships and invitations are coming in the next stage.": "Crea un registro persistente de servidor con un canal de texto #general. Las conversaciones compartidas en canales, la gestión de miembros y las invitaciones llegarán en la próxima etapa.",
