    "Your space, together": "Seu espaço, juntos",
    "Welcome back.": "Bem vindo de volta.",
    "Sign in to restore your profile and friends.": "Faça login para restaurar seu perfil e amigos.",
    "Account access": "Acesso à conta",
    "Email address": "Endereço de e-mail",
    "Password": "Senha",
    "Enter your password": "Digite sua senha",
    "Show password": "Mostrar senha",
    "Use at least 12 characters.": "Utilize pelo menos 12 caracteres.",
    "Privacy notice and your rights": "Aviso de privacidade e seus direitos",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.": "Emanuel Queiroz (snoopeh) opera o serviço de conta opcional da Vumiro. Solicitações de privacidade e relatórios de incidentes: snopeeh@gmail.com. Usamos seu e-mail para fazer login e restaurar seu perfil, amigos, bloqueios, dispositivos e preferências. Biografias opcionais, planos de fundo de perfil e links de provedores inseridos manualmente são compartilhados diretamente com amigos conectados e incluídos no backup de sua própria conta. Links não são integrações verificadas. O Google ou a Microsoft compartilham seu e-mail e perfil básico somente quando você escolhe uma opção de login ativada.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth está hospedado em São Paulo, Brasil; O armazenamento da conta Cloudflare D1 está localizado no leste da América do Norte; Brevo entrega e-mails de contas usando infraestrutura hospedada na UE. Os provedores também processam informações operacionais internacionalmente. Sua identidade de assinatura é criptografada no aplicativo antes do backup. Outros campos sincronizados podem ser lidos por operadores e provedores autorizados. Telas, áudio, bate-papo, senhas de salas, chaves privadas brutas e códigos de recuperação não são carregados no serviço de conta.",
    "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.": "Você pode exportar, corrigir ou excluir dados da conta nas configurações; os dados do dispositivo local permanecem. Separadamente, o diretório de conexão retém os mapeamentos de identificação para amigo e de repetição de migração sem expiração automática; excluir uma conta Supabase não as apaga. Os contadores de alocação de IP com hash por hora expiram após a janela horária. As exclusões de identidade de autenticação com falha permanecem pendentes para nova tentativa até serem concluídas. O aviso completo, versão 2026-11-03, é enviado como PRIVACY.md (Windows) ou licenses/PRIVACY.md (Linux) e explica retenção, processamento de e-mail e seus direitos. Nunca envie senhas ou segredos de recuperação ao suporte.",
    "I reviewed the privacy notice": "Analisei o aviso de privacidade",
