    "Your name. Your space.": "Seu nome. Seu espaço.",
    "Create your local identity, then find your people.": "Crie sua identidade local e depois encontre seu povo.",
    "What should friends call you?": "Como os amigos devem chamá-lo?",
    "Your display name": "Seu nome de exibição",
    "Your signing key stays on this device. Create a Vumiro account in Profile settings to sync your profile and friends between devices.": "Sua chave de assinatura permanece neste dispositivo. Crie uma conta Vumiro nas configurações de perfil para sincronizar seu perfil e amigos entre dispositivos.",
    "Create local profile": "Criar perfil local",
    "Bring a friend.": "Traga um amigo.",
    "Search their name while they’re online and choose their unique name#code, or paste their contact code. They’ll get a request to accept. Existing numeric tags still work.": "Pesquise o nome deles enquanto eles estão online e escolha seu nome exclusivo#código ou cole seu código de contato. Eles receberão um pedido para aceitar. As tags numéricas existentes ainda funcionam.",
    "Friend tag, username or contact code": "Tag de amigo, nome de usuário ou código de contato",
