    "Leave blank to follow their current name": "Deixe em branco para seguir o nome atual",
    "Offline? Save a contact code locally. Mutual contact lists are needed for calls until your friend accepts a request or saves your code.": "Off-line? Salve um código de contato localmente. Listas de contatos mútuos são necessárias para chamadas até que seu amigo aceite uma solicitação ou salve seu código.",
