    "Adjust cover": "Ajustar a tampa",
    "Remove cover": "Remover a tampa",
    "High-resolution covers keep up to 3840 × 1280 pixels. Adjust framing before saving. Only the finished cover is shared or backed up; the original stays on this device.": "As capas de alta resolução mantêm até 3840 × 1280 pixels. Ajuste o enquadramento antes de salvar. Somente a capa finalizada é compartilhada ou armazenada em backup; o original permanece neste dispositivo.",
