    "e.g. your.name": "por exemplo seu.nome",
    "Use 3–24 letters, numbers, dots, underscores or hyphens. Your friend tag adds a unique #code, so people can share a username. Named tags require the updated connection service.": "Use de 3 a 24 letras, números, pontos, sublinhados ou hífens. Sua tag de amigo adiciona um #code exclusivo, para que as pessoas possam compartilhar um nome de usuário. Tags nomeadas requerem o serviço de conexão atualizado.",
    "About you": "Sobre você",
    "A short introduction": "Uma breve introdução",
