    "Your links": "Seus links",
    "Add up to five links. Friends can open them from your profile card.": "Adicione até cinco links. Os amigos podem abri-los no seu cartão de perfil.",
    "Steam profile link": "Link do perfil Steam",
    "Spotify profile link": "Link do perfil Spotify",
