    "These are profile links, not verified account connections.": "Estes são links de perfil, não conexões de conta verificadas.",
    "Save profile": "Salvar perfil",
    "Preview profile": "Perfil de visualização",
    "Your friend tag": "Sua etiqueta de amigo",
    "Connect to assign your tag": "Conecte-se para atribuir sua tag",
    "Copy tag": "Copiar etiqueta",
    "Share your name#code to add friends while you are both online. Its code belongs to this signing identity. Older services show your existing numeric tag until updated.": "Compartilhe seu nome#código para adicionar amigos enquanto vocês dois estiverem online. Seu código pertence a esta identidade de assinatura. Os serviços mais antigos mostram sua tag numérica existente até serem atualizados.",
    "Your contact code": "Seu código de contato",
    "A short public key for finding you. Your photo, display name and private key are never included.": "Uma pequena chave pública para encontrar você. Sua foto, nome de exibição e chave privada nunca são incluídos.",
    "Your public contact code": "Seu código de contato público",
    "Copy contact code": "Copiar código de contato",
    "Save contact code": "Salvar código de contato",
    "Clearing this app’s local data creates a different identity. Your signing key stays nonextractable on this device.": "Limpar os dados locais deste aplicativo cria uma identidade diferente. Sua chave de assinatura permanece inextraível neste dispositivo.",
    "Vumiro account · sync and recovery": "Conta Vumiro · sincronização e recuperação",
    "An optional account restores your profile, friends, blocks and stream preferences on another device. Your signing identity is encrypted in the app before backup; unlock it with your backup password or identity recovery code to restore the same contact identity.": "Uma conta opcional restaura seu perfil, amigos, bloqueios e preferências de transmissão em outro dispositivo. Sua identidade de assinatura é criptografada no aplicativo antes do backup; desbloqueie-o com sua senha de backup ou código de recuperação de identidade para restaurar a mesma identidade de contato.",
    "Not signed in. Your existing local data stays on this device.": "Sem login. Seus dados locais existentes permanecem neste dispositivo.",
    "Email": "E-mail",
    "Password recovery email": "E-mail de recuperação de senha",
    "Confirm your password before this security change": "Confirme sua senha antes desta alteração de segurança",
    "Restore account data to this device": "Restaurar dados da conta para este dispositivo",
    "Back up this device to your account": "Faça backup deste dispositivo em sua conta",
    "Revoke a lost device to block its saved account session from syncing.": "Revogar um dispositivo perdido para bloquear a sincronização de sua sessão de conta salva.",
    "Your email and password are handled by the authentication provider. Your profile, friends, blocks, and settings are synced through the Vumiro account service.": "Seu e-mail e senha são gerenciados pelo provedor de autenticação. Seu perfil, amigos, bloqueios e configurações são sincronizados através do serviço de conta Vumiro.",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email, profile, friends' public contact details and local nicknames, blocks, device activity and preferences to sign you in and restore your account across devices. Optional bios, backgrounds and manually entered provider links are exchanged directly with connected friends and included in your own profile backup. Friends' cached profile-card details are excluded from your backup. Links are not verified integrations.": "Emanuel Queiroz (snoopeh) opera o serviço de conta opcional da Vumiro. Solicitações de privacidade e relatórios de incidentes: snopeeh@gmail.com. Usamos seu e-mail, perfil, detalhes de contato público de amigos e apelidos locais, bloqueios, atividade de dispositivo e preferências para fazer login e restaurar sua conta em vários dispositivos. Biografias opcionais, planos de fundo e links de provedores inseridos manualmente são trocados diretamente com amigos conectados e incluídos em seu próprio backup de perfil. Os detalhes do cartão de perfil em cache dos amigos são excluídos do seu backup. Links não são integrações verificadas.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing-identity backup is encrypted in the app; other synced fields are readable by authorized operators and providers. Screens, voice, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth está hospedado em São Paulo, Brasil; O armazenamento da conta Cloudflare D1 está localizado no leste da América do Norte; Brevo entrega e-mails de contas usando infraestrutura hospedada na UE. Os provedores também processam informações operacionais internacionalmente. Seu backup de identidade de assinatura é criptografado no aplicativo; outros campos sincronizados podem ser lidos por operadores e provedores autorizados. Telas, voz, bate-papo, senhas de salas, chaves privadas brutas e códigos de recuperação não são carregados no serviço de conta.",
    "You can export account data, correct your profile, sign out and delete your account here. Deletion removes synced data and requests deletion of the authentication identity. Failed provider deletions stay pending for automatic retry until completed. Local device data and signing keys remain on this device. The separate connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry, independently of account deletion. Hourly hashed IP allocation counters expire after their hourly window. There is no in-app directory-record deletion control; contact the operator about those records. Never send passwords, verification codes, recovery codes or private keys to support.": "Você pode exportar dados da conta, corrigir seu perfil, sair e excluir sua conta aqui. A exclusão remove os dados sincronizados e solicita a exclusão da identidade de autenticação. As exclusões de provedores com falha permanecem pendentes para nova tentativa automática até serem concluídas. Os dados do dispositivo local e as chaves de assinatura permanecem neste dispositivo. O diretório de conexão separado retém mapeamentos de identidade para tag de amigo e de repetição de migração sem expiração automática, independentemente da exclusão da conta. Os contadores de alocação de IP com hash por hora expiram após a janela horária. Não há controle de exclusão de registros de diretório no aplicativo; entre em contato com a operadora sobre esses registros. Nunca envie senhas, códigos de verificação, códigos de recuperação ou chaves privadas para o suporte.",
    "The full notice, version 2026-11-03, included with Vumiro explains retention, provider processing and your rights. The account service does not provide end-to-end encryption for profile and contact fields.": "O aviso completo, versão 2026-11-03, incluído no Vumiro explica a retenção, o processamento do provedor e seus direitos. O serviço de conta não fornece criptografia ponta a ponta para campos de perfil e contato.",
    "Registration records that you reviewed this notice. The full account privacy notice ships with Vumiro as": "Registro registra que você revisou este aviso. O aviso completo de privacidade da conta é enviado com o Vumiro como",
    "Screen sharing settings": "Configurações de compartilhamento de tela",
    "Your defaults also apply to the open room. Actual quality depends on the screen, device and connection.": "Seus padrões também se aplicam à sala aberta. A qualidade real depende da tela, do dispositivo e da conexão.",
