    "App sounds": "Sons do aplicativo",
    "Short cues for calls, chat, friend requests and room activity. This volume is separate from voice and screen audio.": "Dicas curtas para chamadas, bate-papo, solicitações de amizade e atividades na sala. Este volume é separado da voz e do áudio da tela.",
    "Play app sounds": "Reproduzir sons de aplicativos",
