    "0% mutes notifications; up to 300% makes quiet alerts louder. Preview plays once at the selected volume, even when app sounds are off. Save to apply changes.": "0% silencia notificações; até 300% torna os alertas silenciosos mais altos. A visualização é reproduzida uma vez no volume selecionado, mesmo quando os sons do aplicativo estão desligados. Salve para aplicar as alterações.",
