    "Installing restarts Vumiro and preserves your local profile and friends. Leave your room before installing.": "A instalação reinicia o Vumiro e preserva seu perfil local e amigos. Saia da sua sala antes de instalar.",
    "Stream diagnostics": "Diagnóstico da transmissão",
    "If a share fails, export the last 24 hours of technical events. Windows includes the previous session status. History has a size limit and contains no audio, video, chats, credentials or peer addresses.": "Se um compartilhamento falhar, exporte as últimas 24 horas de eventos técnicos. O Windows inclui o status da sessão anterior. O histórico tem um limite de tamanho e não contém áudio, vídeo, bate-papos, credenciais ou endereços de pares.",
    "Export diagnostic logs": "Exportar logs de diagnóstico",
    "QA notification tests": "Testes de notificação de QA",
