    "Accounts are temporarily unavailable. You can continue with your local profile.": "As contas estão temporariamente indisponíveis. Você pode continuar com seu perfil local.",
    "New account registration is paused. Existing accounts can sign in.": "O registro de nova conta é pausado. As contas existentes podem fazer login.",
    "does not upload your device signing key": "não carrega a chave de assinatura do seu dispositivo",
    "Vumiro uploads only the client-encrypted identity envelope. It does not upload the raw signing key, identity recovery code, room passwords, screen, voice, or chat.": "Vumiro carrega apenas o envelope de identidade criptografado pelo cliente. Ele não carrega a chave de assinatura bruta, o código de recuperação de identidade, as senhas das salas, a tela, a voz ou o bate-papo.",
    "Account data is not end-to-end encrypted": "Os dados da conta não são criptografados de ponta a ponta",
    "The signing-identity envelope is encrypted in the client. Other synced account fields are readable to authorized Vumiro infrastructure operators and providers.": "O envelope de identidade de assinatura é criptografado no cliente. Outros campos de conta sincronizados podem ser lidos por operadores e provedores autorizados de infraestrutura Vumiro.",
