    "Set a separate Vumiro password to enable encrypted identity backup and email sign-in. Your Google or Microsoft password is never requested.": "Defina uma senha Vumiro separada para permitir backup de identidade criptografada e login de e-mail. Sua senha do Google ou da Microsoft nunca é solicitada.",
