    "Accounts are not available yet. You can continue with your local profile and try again later.": "As contas ainda não estão disponíveis. Você pode continuar com seu perfil local e tentar novamente mais tarde.",
    "The account service is not configured.": "O serviço de conta não está configurado.",
    "The account service returned an invalid authentication address.": "O serviço de conta retornou um endereço de autenticação inválido.",
    "The authentication address is not a trusted Supabase project.": "O endereço de autenticação não é um projeto Supabase confiável.",
