    "Vumiro account service is temporarily unavailable. Your local profile remains available.": "O serviço de conta Vumiro está temporariamente indisponível. Seu perfil local permanece disponível.",
    "This app version does not provide secure account session storage. Update Vumiro before signing in.": "Esta versão do aplicativo não fornece armazenamento seguro de sessões de conta. Atualize o Vumiro antes de entrar.",
    "The account provider did not return a valid session.": "O provedor da conta não retornou uma sessão válida.",
