    "The saved settings are invalid.": "As configurações salvas são inválidas.",
    "Update Vumiro to review the current privacy notice before creating an account or backing up. Existing accounts can still sign in.": "Atualize o Vumiro para revisar o aviso de privacidade atual antes de criar uma conta ou fazer backup. As contas existentes ainda podem fazer login.",
    "Review and acknowledge the privacy notice before syncing account data.": "Revise e confirme o aviso de privacidade antes de sincronizar os dados da conta.",
