    "This account has no saved profile. Choose “Back up this device” to copy this device’s profile and friends to this account.": "Esta conta não possui perfil salvo. Escolha “Fazer backup deste dispositivo” para copiar o perfil e os amigos deste dispositivo para esta conta.",
    "Google and Microsoft cannot unlock your encrypted contact identity. Enter your Vumiro password or recovery code below.": "Google e Microsoft não podem desbloquear sua identidade de contato criptografada. Digite sua senha Vumiro ou código de recuperação abaixo.",
    "Account data is ready. Sign in with your password, or use your saved identity recovery code after password reset, to restore this contact identity.": "Os dados da conta estão prontos. Faça login com sua senha ou use seu código de recuperação de identidade salvo após a redefinição de senha para restaurar essa identidade de contato.",
