    "Account and synced account data were deleted. Your local device profile remains on this device.": "Os dados da conta e da conta sincronizada foram excluídos. O perfil do seu dispositivo local permanece neste dispositivo.",
    "Synced account data was deleted. Account identity deletion is pending and Vumiro will retry automatically. Your local device profile remains on this device.": "Os dados da conta sincronizada foram excluídos. A exclusão da identidade da conta está pendente e o Vumiro tentará novamente automaticamente. O perfil do seu dispositivo local permanece neste dispositivo.",
    "Your email still needs verification. Enter the code from your signup email, or resend it.": "Seu e-mail ainda precisa de verificação. Insira o código do seu e-mail de inscrição ou reenvie-o.",
