    "Replace this device’s profile, contacts, blocks, stream settings, and compatible signed identity with the copy saved in your account?": "Substituir o perfil, os contatos, os bloqueios, as configurações de transmissão e a identidade assinada compatível deste dispositivo pela cópia salva em sua conta?",
