    "Copy this device’s profile, friends, settings, and encrypted recovery identity into the signed-in account? This may replace data already saved there.": "Copiar o perfil, os amigos, as configurações e a identidade de recuperação criptografada deste dispositivo para a conta conectada? Isso pode substituir os dados já salvos lá.",
