    "Connection interrupted. Rejoining in {seconds} seconds…": "Conexão interrompida. Voltando em {seconds} segundos…",
    "Waiting for the room owner. Trying again in {seconds} seconds…": "Esperando pelo dono da sala. Tentando novamente em {seconds} segundos…",
    "An account restores your profile, friends, blocks, stream preferences, and an encrypted signing identity on another device. Enabling recovery for an older profile changes its contact code; updated friends verify the signed transition automatically while older app versions may require a new friend acceptance.": "Uma conta restaura seu perfil, amigos, bloqueios, preferências de transmissão e uma identidade de assinatura criptografada em outro dispositivo. Ativar a recuperação de um perfil mais antigo altera seu código de contato; amigos atualizados verificam a transição assinada automaticamente, enquanto versões mais antigas do aplicativo podem exigir a aceitação de um novo amigo.",
    "Profile backed up. High-resolution covers still stay on this device and share directly with updated friends; private cover backup is not enabled on the service yet.": "Perfil com backup. As capas de alta resolução ainda permanecem neste dispositivo e são compartilhadas diretamente com amigos atualizados; o backup de cobertura privada ainda não está habilitado no serviço.",
    "This device is backed up. Only the finished cover is backed up; the editable original stays on this device. Changes will sync automatically while Vumiro is open.": "Foi feito backup deste dispositivo. Somente a capa finalizada é copiada; o original editável permanece neste dispositivo. As alterações serão sincronizadas automaticamente enquanto o Vumiro estiver aberto.",
    "Identity recovery is enabled. Save the recovery code before closing this panel. Your contact code changed; older friends may need to accept a new request.": "A recuperação de identidade está habilitada. Salve o código de recuperação antes de fechar este painel. Seu código de contato foi alterado; amigos mais velhos podem precisar aceitar uma nova solicitação.",
    "0% mutes; 100% is original volume; up to 400% boosts quiet audio (may distort)": "0% mudos; 100% é o volume original; até 400% aumenta o áudio silencioso (pode distorcer)",
    "Friend request resolved; the blocked identity was not added.": "Pedido de amizade resolvido; a identidade bloqueada não foi adicionada.",
