    "Your username is saved. Shared usernames need the updated Vumiro service; use your existing tag or contact code for now.": "Seu nome de usuário foi salvo. Nomes de usuário compartilhados precisam do serviço Vumiro atualizado; use sua tag ou código de contato existente por enquanto.",
    "Service offline. Reconnecting automatically; you can also use Reconnect.": "Serviço off-line. Reconectando automaticamente; você também pode usar Reconectar.",
