    "Clearing this app’s local data creates a different identity. Your signing key stays nonextractable on this device.": "このアプリのローカルデータをクリアすると、別のアイデンティティが作成されます。署名キーはこのデバイスでは抽出不可能なままです。",
    "Vumiro account · sync and recovery": "Vumiroアカウント・同期と回復",
    "An optional account restores your profile, friends, blocks and stream preferences on another device. Your signing identity is encrypted in the app before backup; unlock it with your backup password or identity recovery code to restore the same contact identity.": "オプションのアカウントは、あなたのプロフィール、友達、ブロック、およびストリーム設定を別のデバイスに復元します。署名 ID はバックアップ前にアプリ内で暗号化されます。バックアップ パスワードまたは ID 回復コードを使用してロックを解除し、同じ連絡先 ID を復元します。",
