    "Connection interrupted. Rejoining in {seconds} seconds…": "接続が中断されました。 {seconds} 秒後に再接続します…",
    "Waiting for the room owner. Trying again in {seconds} seconds…": "部屋のオーナーを待っています。 {seconds} 秒後に再試行します…",
    "An account restores your profile, friends, blocks, stream preferences, and an encrypted signing identity on another device. Enabling recovery for an older profile changes its contact code; updated friends verify the signed transition automatically while older app versions may require a new friend acceptance.": "アカウントは、あなたのプロフィール、友達、ブロック、ストリーム設定、および暗号化された署名 ID を別のデバイスに復元します。古いプロファイルのリカバリを有効にすると、その連絡先コードが変更されます。更新された友達は署名された移行を自動的に検証しますが、古いアプリのバージョンでは新しい友達の承認が必要になる場合があります。",
    "Profile backed up. High-resolution covers still stay on this device and share directly with updated friends; private cover backup is not enabled on the service yet.": "プロファイルがバックアップされました。高解像度のカバーは引き続きこのデバイスに残り、更新された友人と直接共有します。プライベート カバー バックアップはサービスでまだ有効になっていません。",
    "This device is backed up. Only the finished cover is backed up; the editable original stays on this device. Changes will sync automatically while Vumiro is open.": "このデバイスはバックアップされています。完成したカバーのみがバックアップされます。編集可能なオリジナルはこのデバイス上に残ります。 Vumiro が開いている間、変更は自動的に同期されます。",
    "Identity recovery is enabled. Save the recovery code before closing this panel. Your contact code changed; older friends may need to accept a new request.": "ID 回復が有効になっています。このパネルを閉じる前にリカバリ コードを保存してください。連絡先コードが変更されました。年上の友人は新しいリクエストを受け入れる必要があるかもしれません。",
    "0% mutes; 100% is original volume; up to 400% boosts quiet audio (may distort)": "0% がミュートします。 100% は元のボリュームです。静かな音声を最大 400% ブーストします (歪む可能性があります)",
    "Friend request resolved; the blocked identity was not added.": "フレンドリクエストは解決されました。ブロックされた ID は追加されませんでした。",
    "Online. Named tags need the updated Vumiro service; your existing tag and contact code still work.": "オンライン。名前付きタグには、更新された Vumiro サービスが必要です。既存のタグと連絡先コードは引き続き機能します。",
    "Your username is saved. Shared usernames need the updated Vumiro service; use your existing tag or contact code for now.": "ユーザー名が保存されました。共有ユーザー名には、更新された Vumiro サービスが必要です。現時点では、既存のタグまたは連絡先コードを使用してください。",
    "Service offline. Reconnecting automatically; you can also use Reconnect.": "サービスがオフラインです。自動的に再接続します。再接続を使用することもできます。",
    "display-capture; microphone; speaker-selection; autoplay; fullscreen": "ディスプレイキャプチャ;マイクロフォン;スピーカーの選択。自動再生;全画面表示",
    "{p0}’s code is valid. Reconnect to send a request; they must also be online.": "{p0}のコードは有効です。再接続してリクエストを送信します。オンラインである必要もあります。",
    "’s code is valid. Reconnect to send a request; they must also be online.": "のコードは有効です。再接続してリクエストを送信します。オンラインである必要もあります。",
