    "Use at least 12 characters.": "使用至少12个字符。",
    "Privacy notice and your rights": "隐私声明和您的权利",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.": "Emanuel Queiroz (snoopeh)运营Vumiro的可选账户服务。隐私请求和事件报告：snopeeh@gmail.com。我们使用您的电子邮件让您登录并恢复您的个人资料、好友、区块、设备和偏好设置。可选的个人简介、个人资料背景和手动输入的提供商链接直接与连接的朋友共享，并包含在您自己的帐户备份中。链接不是经过验证的集成。仅当您选择启用的登录选项时，Google 或 Microsoft 才会共享您的电子邮件和基本个人资料。",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth在巴西圣保罗托管； Cloudflare D1 帐户存储位于北美东部； Brevo 使用欧盟托管的基础设施传送帐户电子邮件。提供商还处理国际运营信息。您的签名身份在备份前已在应用程序中加密。其他同步字段可由授权操作员和提供商读取。屏幕、音频、聊天、房间密码、原始私钥和恢复代码不会上传到帐户服务。",
    "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.": "您可以在设置中导出、更正或删除账户数据；本地设备数据保留。另外，连接目录保留身份到朋友标签和迁移重放映射，不会自动过期；删除 Supabase 帐户并不会删除它们。每小时哈希 IP 分配计数器在其每小时窗口后过期。失败的身份验证身份删除仍待重试，直至完成。完整通知版本 2026-11-03 以 PRIVACY.md (Windows) 或 licenses/PRIVACY.md (Linux) 形式提供，并解释了保留、电子邮件处理和您的权利。切勿向支持人员发送密码或恢复机密。",
