    "Your display name": "您的显示名称",
    "Your signing key stays on this device. Create a Vumiro account in Profile settings to sync your profile and friends between devices.": "您的签名密钥保留在此设备上。在“个人资料”设置中创建 Vumiro 帐户,以在设备之间同步您的个人资料和好友。",
