    "Search their name while they’re online and choose their unique name#code, or paste their contact code. They’ll get a request to accept. Existing numeric tags still work.": "当他们在线时搜索他们的姓名并选择他们的唯一名称#代码,或粘贴他们的联系代码。他们会收到接受请求。现有的数字标签仍然有效。",
