    "Use 3–24 letters, numbers, dots, underscores or hyphens. Your friend tag adds a unique #code, so people can share a username. Named tags require the updated connection service.": "使用3-24个字母、数字、点、下划线或连字符。您的朋友标签添加了一个唯一的#code,以便人们可以共享用户名。命名标签需要更新的连接服务。",
