    "Share your name#code to add friends while you are both online. Its code belongs to this signing identity. Older services show your existing numeric tag until updated.": "分享您的姓名#代码以在你们都在线时添加朋友。它的代码属于这个签名身份。较旧的服务会显示您现有的数字标签,直到更新为止。",
