    "Vumiro account · sync and recovery": "Vumiro 帐户·同步和恢复",
    "An optional account restores your profile, friends, blocks and stream preferences on another device. Your signing identity is encrypted in the app before backup; unlock it with your backup password or identity recovery code to restore the same contact identity.": "可选帐户在另一设备上恢复您的个人资料、朋友、块和流首选项。您的签名身份在备份前已在应用程序中加密;使用您的备份密码或身份恢复代码解锁以恢复相同的联系人身份。",
