    "Confirm your password before this security change": "在此安全更改之前确认您的密码",
    "Restore account data to this device": "将帐户数据恢复到该设备",
    "Back up this device to your account": "将此设备备份到您的帐户",
    "Revoke a lost device to block its saved account session from syncing.": "撤销丢失的设备以阻止其保存的帐户会话同步。",
    "Your email and password are handled by the authentication provider. Your profile, friends, blocks, and settings are synced through the Vumiro account service.": "您的电子邮件和密码由验证提供商处理。您的个人资料、朋友、区块和设置通过 Vumiro 帐户服务同步。",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email, profile, friends' public contact details and local nicknames, blocks, device activity and preferences to sign you in and restore your account across devices. Optional bios, backgrounds and manually entered provider links are exchanged directly with connected friends and included in your own profile backup. Friends' cached profile-card details are excluded from your backup. Links are not verified integrations.": "Emanuel Queiroz (snoopeh)操作Vumiro的可选帐户服务。隐私请求和事件报告:snopeeh@gmail.com。我们使用您的电子邮件、个人资料、朋友的公开联系方式以及本地昵称、区块、设备活动和偏好来让您登录并跨设备恢复您的帐户。可选的个人简介、背景和手动输入的提供商链接直接与连接的朋友交换,并包含在您自己的个人资料备份中。朋友的缓存个人资料卡详细信息将从您的备份中排除。链接不是经过验证的集成。",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing-identity backup is encrypted in the app; other synced fields are readable by authorized operators and providers. Screens, voice, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth在巴西圣保罗托管; Cloudflare D1 帐户存储位于北美东部; Brevo 使用欧盟托管的基础设施传送帐户电子邮件。提供商还处理国际运营信息。您的签名身份备份在应用程序中进行了加密;其他同步字段可由授权操作员和提供商读取。屏幕、语音、聊天、房间密码、原始私钥和恢复代码不会上传到帐户服务。",
    "You can export account data, correct your profile, sign out and delete your account here. Deletion removes synced data and requests deletion of the authentication identity. Failed provider deletions stay pending for automatic retry until completed. Local device data and signing keys remain on this device. The separate connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry, independently of account deletion. Hourly hashed IP allocation counters expire after their hourly window. There is no in-app directory-record deletion control; contact the operator about those records. Never send passwords, verification codes, recovery codes or private keys to support.": "您可以在此处导出帐户数据、更正您的个人资料、注销和删除您的帐户。删除会删除同步数据并请求删除身份验证身份。失败的提供程序删除将等待自动重试,直至完成。本地设备数据和签名密钥保留在此设备上。单独的连接目录保留身份到朋友标签和迁移重播映射,不会自动过期,与帐户删除无关。每小时哈希 IP 分配计数器在其每小时窗口后过期。应用内没有目录记录删除控制;联系运营商了解这些记录。切勿向支持人员发送密码、验证码、恢复码或私钥。",
    "The full notice, version 2026-11-03, included with Vumiro explains retention, provider processing and your rights. The account service does not provide end-to-end encryption for profile and contact fields.": "Vumiro 中包含的完整通知版本 2026-11-03 解释了保留、提供商处理和您的权利。帐户服务不为个人资料和联系人字段提供端到端加密。",
    "Registration records that you reviewed this notice. The full account privacy notice ships with Vumiro as": "您审阅本通知的注册记录。完整的帐户隐私声明随 Vumiro 一起提供",
    "Screen sharing settings": "屏幕共享设置",
    "Your defaults also apply to the open room. Actual quality depends on the screen, device and connection.": "您的默认值也适用于开放房间。实际质量取决于屏幕、设备和连接。",
    "Frames per second": "每秒帧数",
    "Bitrate per participant · Mbps": "每个参与者的比特率·Mbps",
    "Native display": "本机显示",
