    "Motion and video": "运动和视频",
    "Include screen audio when available": "当可用时包括屏幕音频",
    "Microphone works on Linux, but system audio capture is not supported in this release.": "麦克风在Linux上工作,但在此版本中不支持系统音频捕获。",
    "App sounds": "应用程序声音",
    "Short cues for calls, chat, friend requests and room activity. This volume is separate from voice and screen audio.": "呼叫、聊天、好友请求和房间活动的简短提示。该音量与语音和屏幕音频分开。",
    "Play app sounds": "播放应用程序声音",
    "Notification volume ·": "通知量·",
    "0% mutes notifications; up to 300% makes quiet alerts louder. Preview plays once at the selected volume, even when app sounds are off. Save to apply changes.": "0%使通知静音;高达 300% 会使安静的警报声音更大。即使应用程序声音关闭,预览也会以选定的音量播放一次。保存以应用更改。",
    "Preview sound": "预览声音",
    "Save sound settings": "保存声音设置",
    "Choose which activity draws attention and plays a sound. Notification sound volume is set under App sounds. Activity stays in your notification list even when alerts are muted.": "选择哪个活动引起注意并播放声音。通知音量在应用程序声音下设置。即使警报已静音,活动也会保留在您的通知列表中。",
