    "Installing restarts Vumiro and preserves your local profile and friends. Leave your room before installing.": "安装将重新启动 Vumiro 并保留您的本地配置文件和朋友。安装前离开房间。",
    "Stream diagnostics": "流诊断",
    "If a share fails, export the last 24 hours of technical events. Windows includes the previous session status. History has a size limit and contains no audio, video, chats, credentials or peer addresses.": "如果共享失败,则导出最近24小时的技术事件。 Windows 包含先前的会话状态。历史记录有大小限制,不包含音频、视频、聊天、凭证或对等地址。",
    "Export diagnostic logs": "导出诊断日志",
    "QA notification tests": "QA通知测试",
    "Preview call, friend request, and room alerts locally. These previews do not send requests or open rooms.": "在本地预览呼叫、好友请求和房间警报。这些预览不会发送请求或打开房间。",
