    "Enter the verification code we sent to your email address.": "输入我们发送到您的电子邮件地址的验证码。",
    "Forgot your password?": "忘记密码了?",
    "We’ll send a recovery code to your account email.": "我们会将恢复代码发送到您的帐户电子邮件。",
