    "Enter the code from your recovery email and set a new password.": "输入恢复电子邮件中的代码并设置新密码。",
    "Bring your friends with you.": "带上你的朋友一起来。",
    "Unlock your encrypted Vumiro identity.": "解锁您的加密的Vumiro身份。",
    "Your account.": "您的帐户。",
    "Manage your saved data, linked devices and account security.": "管理您保存的数据、链接的设备和帐户安全。",
    "Accounts are temporarily unavailable. You can continue with your local profile.": "帐户暂时不可用。您可以继续使用您的本地个人资料。",
    "New account registration is paused. Existing accounts can sign in.": "新帐户注册被暂停。现有帐户可以登录。",
    "does not upload your device signing key": "不上传您的设备签名密钥",
    "Vumiro uploads only the client-encrypted identity envelope. It does not upload the raw signing key, identity recovery code, room passwords, screen, voice, or chat.": "Vumiro仅上传客户端加密的身份信封。它不会上传原始签名密钥、身份恢复代码、房间密码、屏幕、语音或聊天。",
    "Account data is not end-to-end encrypted": "账户数据未端到端加密",
    "The signing-identity envelope is encrypted in the client. Other synced account fields are readable to authorized Vumiro infrastructure operators and providers.": "签名身份信封在客户端中被加密。其他同步帐户字段可供授权的 Vumiro 基础设施运营商和提供商读取。",
    "Resend code": "重新发送代码",
    "Sign out everywhere": "到处注销",
    "Current password": "当前密码",
    "Identity recovery code (if not saved on this device)": "身份恢复代码(如果未保存在此设备上)",
    "Change password": "更改密码",
    "Identity recovery code (optional)": "身份恢复码(可选)",
    "Use the identity code saved when recovery was enabled to preserve the same contact identity after resetting your password.": "使用启用恢复时保存的身份代码来在重置密码后保留相同的联系人身份。",
    "Save your identity recovery code": "保存您的身份恢复码",
    "Keep an offline copy. Vumiro cannot restore the same contact identity after a password reset without this code.": "保留离线副本。如果没有此代码,Vumiro 无法在重置密码后恢复相同的联系人身份。",
    "Copy code": "复制代码",
    "Save code": "保存代码",
    "I saved it": "我保存了",
    "Add a Vumiro password": "添加 Vumiro 密码",
    "Set a separate Vumiro password to enable encrypted identity backup and email sign-in. Your Google or Microsoft password is never requested.": "设置单独的Vumiro密码以启用加密身份备份和电子邮件登录。永远不会要求您输入 Google 或 Microsoft 密码。",
    "New Vumiro password": "新Vumiro密码",
    "Confirm Vumiro password": "确认Vumiro密码",
    "Set Vumiro password": "设置 Vumiro 密码",
    "Password and identity recovery": "密码和身份恢复",
    "This sign-in option is not available yet. You can continue locally.": "该登录选项尚不可用。您可以在本地继续。",
    "Open the Vumiro desktop app to sign in with Google or Microsoft.": "打开 Vumiro 桌面应用程序以使用 Google 或 Microsoft 登录。",
    "The browser sign-in expired. Please try again.": "浏览器登录已过期。请再试一次。",
    "The browser did not return a valid sign-in code.": "浏览器未返回有效的登录代码。",
    "Review the privacy notice before creating an account.": "在创建帐户之前查看隐私声明。",
    "Sign in with the same account to confirm this change.": "使用同一帐户登录以确认此更改。",
    "The provider did not return a valid confirmation.": "提供者没有返回有效的确认。",
    "The account service could not complete this request.": "账户服务无法完成该请求。",
    "Accounts are not available yet. You can continue with your local profile and try again later.": "账户尚不可用。您可以继续使用本地配置文件,稍后再试。",
    "The account service is not configured.": "帐户服务未配置。",
    "The account service returned an invalid authentication address.": "帐户服务返回无效的认证地址。",
    "The authentication address is not a trusted Supabase project.": "认证地址不是受信任的Supabase项目。",
    "The account service returned an invalid publishable key.": "帐户服务返回无效的可发布密钥。",
    "Vumiro account service is temporarily unavailable. Your local profile remains available.": "Vumiro账户服务暂时不可用。您的本地个人资料仍然可用。",
    "This app version does not provide secure account session storage. Update Vumiro before signing in.": "该应用程序版本不提供安全帐户会话存储。登录前更新 Vumiro。",
    "The account provider did not return a valid session.": "帐户提供者没有返回有效会话。",
    "Sign in to your Vumiro account first.": "首先登录您的 Vumiro 帐户。",
    "The account service did not return valid device credentials.": "帐户服务没有返回有效的设备凭证。",
    "This device is no longer authorized. Sign in again to link it as a new device.": "该设备不再被授权。再次登录以将其链接为新设备。",
    "Private high-resolution cover backup is not enabled on this service yet.": "该服务尚未启用私人高分辨率封面备份。",
