    "Cover transfer timed out. Your local cover is unchanged. Try again.": "封面传输超时。您的本地保险不变。再试一次。",
    "The downloaded cover exceeds its size limit.": "下载的封面超出其大小限制。",
    "The cover changed during backup. Try again.": "封面在备份期间改变。再试一次。",
    "The service did not confirm the finished cover.": "服务未确认完成的封面。",
    "This app version cannot restore the encrypted account identity. Update Vumiro and try again.": "该应用程序版本无法恢复加密的帐户身份。更新 Vumiro 并重试。",
    "Enter your account password or saved identity recovery code to restore this contact identity on a new device.": "输入您的帐户密码或保存的身份恢复代码以在新设备上恢复该联系人身份。",
    "The saved account data is invalid.": "保存的帐户数据无效。",
    "The saved profile is invalid.": "保存的配置文件无效。",
    "High-resolution covers are unavailable in this app.": "高分辨率封面在此应用程序中不可用。",
    "The saved profile details are invalid.": "保存的配置文件详细信息无效。",
    "The saved block list is invalid.": "保存的阻止列表无效。",
    "The saved contact list is invalid.": "保存的联系人列表无效。",
    "The saved contact list contains duplicates.": "保存的联系人列表包含重复项。",
    "The saved identity recovery data is invalid.": "保存的身份恢复数据无效。",
    "The saved settings are invalid.": "保存的设置无效。",
    "Update Vumiro to review the current privacy notice before creating an account or backing up. Existing accounts can still sign in.": "更新 Vumiro 以在创建帐户或备份之前查看当前的隐私声明。现有帐户仍然可以登录。",
    "Review and acknowledge the privacy notice before syncing account data.": "在同步帐户数据之前查看并确认隐私声明。",
    "Update Vumiro before enabling identity recovery.": "在启用身份恢复之前更新Vumiro。",
    "Account ready. Your local profile will be backed up after you create it.": "帐户准备好。您的本地配置文件将在您创建后进行备份。",
    "This account has no saved profile. Choose “Back up this device” to copy this device’s profile and friends to this account.": "该帐户没有保存的配置文件。选择“备份此设备”将此设备的个人资料和好友复制到此帐户。",
    "Google and Microsoft cannot unlock your encrypted contact identity. Enter your Vumiro password or recovery code below.": "Google 和 Microsoft 无法解锁您的加密联系人身份。在下面输入您的 Vumiro 密码或恢复代码。",
    "Account data is ready. Sign in with your password, or use your saved identity recovery code after password reset, to restore this contact identity.": "帐户数据已准备好。使用您的密码登录,或在密码重置后使用您保存的身份恢复代码来恢复此联系人身份。",
    "Account data is ready. Create a local profile first, then choose whether to restore it.": "帐户数据已准备好。首先创建本地配置文件,然后选择是否恢复它。",
