    "Account and synced account data were deleted. Your local device profile remains on this device.": "帐户和同步的帐户数据被删除。您的本地设备配置文件仍保留在此设备上。",
    "Synced account data was deleted. Account identity deletion is pending and Vumiro will retry automatically. Your local device profile remains on this device.": "同步的帐户数据被删除。帐户身份删除正在等待,Vumiro 将自动重试。您的本地设备配置文件仍保留在此设备上。",
    "Your email still needs verification. Enter the code from your signup email, or resend it.": "您的电子邮件仍需要验证。输入注册电子邮件中的代码,或重新发送。",
