    "An account restores your profile, friends, blocks, stream preferences, and an encrypted signing identity on another device. Enabling recovery for an older profile changes its contact code; updated friends verify the signed transition automatically while older app versions may require a new friend acceptance.": "帐户会在另一台设备上恢复您的个人资料、好友、区块、流媒体首选项和加密签名身份。启用旧配置文件的恢复会更改其联系代码;更新的朋友会自动验证签名的转换,而较旧的应用程序版本可能需要新的朋友接受。",
    "Profile backed up. High-resolution covers still stay on this device and share directly with updated friends; private cover backup is not enabled on the service yet.": "配置文件已备份。高分辨率封面仍保留在此设备上,并直接与更新的朋友分享;该服务尚未启用私人封面备份。",
    "This device is backed up. Only the finished cover is backed up; the editable original stays on this device. Changes will sync automatically while Vumiro is open.": "该设备已备份。仅备份完成的封面;可编辑的原件保留在此设备上。 Vumiro 打开时,更改将自动同步。",
    "Identity recovery is enabled. Save the recovery code before closing this panel. Your contact code changed; older friends may need to accept a new request.": "身份恢复已启用。在关闭此面板之前保存恢复代码。您的联系代码已更改;年长的朋友可能需要接受新的请求。",
    "0% mutes; 100% is original volume; up to 400% boosts quiet audio (may distort)": "0% 静音; 100%为原始体积;高达 400% 提升安静音频(可能会失真)",
