    "Online. Named tags need the updated Vumiro service; your existing tag and contact code still work.": "在线的。命名标签需要更新的Vumiro服务;您现有的标签和联系代码仍然有效。",
    "Your username is saved. Shared usernames need the updated Vumiro service; use your existing tag or contact code for now.": "您的用户名已保存。共享用户名需要更新Vumiro服务;暂时使用您现有的标签或联系代码。",
    "Service offline. Reconnecting automatically; you can also use Reconnect.": "服务离线。自动重新连接;您还可以使用重新连接。",
