    "Fourteen small sakura petals descend slowly with gentle drift and rotation. Transparent, seamless 28-second vector loop. Reduced-motion preferences hide the effect.": "十四片小樱花花瓣随着轻柔的飘移和旋转缓缓落下。透明、无缝的 28 秒矢量循环。减少运动首选项会隐藏该效果。",
    "Vumiro — Blade reveal": "Vumiro — 刀片展示",
    "A curved red blade cut traces the actual opening in the V and reveals the mark in the center. The V glides left as the outlined Vumiro wordmark reveals and glides right. A brief camera push, roll and damped recoil emphasize the cut. The completed logo holds, then fades out. Duration 4.8 seconds.": "弯曲的红色刀片切割追踪 V 形的实际开口，并显露出中心的标记。当勾勒出的 Vumiro 字标显露出来并向右滑动时，V 向左滑动。短暂的镜头推动、滚动和阻尼后坐力强调了剪辑。完成的徽标保留，然后淡出。持续时间 4.8 秒。",
