    "Launch animation": "启动动画",
    "The Vumiro intro plays once when you fully quit and open the app. Restoring it from the tray or reloading the interface keeps your place.": "完全退出并重新打开应用时，Vumiro开场动画只会播放一次。从托盘恢复窗口或重新加载界面会保留当前状态。",
