    "Your chat, your storage": "聊天存在哪里，由你决定",
    "Signed room text and attachment descriptions are saved on this device. Original attachment files are not archived yet. History belongs to your signing identity and the original room; the account backup does not include chat history.": "带签名的房间文字消息和附件说明会保存在此设备上，附件原始文件暂不归档。历史记录属于你的签名身份和原始房间；账户备份不包含聊天历史。",
