    "Your archive access token": "归档访问令牌",
    "The token is kept for this browser session. Use HTTPS for a remote server, or http://127.0.0.1:8788 on this computer. The archive operator can read stored messages. Changing servers does not move existing history.": "令牌仅在本次浏览器会话中保留。远程服务器请使用HTTPS，本机可使用http://127.0.0.1:8788。归档运营者可以读取已保存的消息。更换服务器不会迁移现有历史记录。",
    "Your archive owner ID:": "归档所有者ID：",
    "Save storage settings": "保存存储设置",
    "Connect to private archive": "连接私人归档",
    "Server groundwork": "服务器功能准备",
    "Create a persistent server record with a #general text channel. Shared channel conversations, memberships and invitations are coming in the next stage.": "创建并持久保存一条包含#general文字频道的服务器记录。共享频道聊天、成员管理和邀请功能将在下一阶段推出。",
    "Server name": "服务器名称",
    "Create server record": "创建服务器记录",
    "Support Vumiro": "支持Vumiro",
    "A little support. More time together.": "一点支持，更多相聚时光。",
    "Vumiro is an independent, open-source project. If it makes your evenings with friends better, you can help keep it moving.": "Vumiro是一个独立的开源项目。如果它让你和朋友共度的夜晚更愉快，你可以支持它继续发展。",
    "Build what's next": "一起打造新功能",
    "Help make room for reliable chat, personal servers and the small details that make Vumiro feel like home.": "帮助我们实现可靠的聊天、个人服务器，以及让Vumiro更有归属感的细节。",
    "Keep it independent": "保持独立",
    "Contributions support development, infrastructure and testing across Windows and Linux.": "捐助将用于开发、基础设施，以及Windows和Linux上的测试。",
    "Always your choice": "始终由你选择",
    "Supporting is optional. There are no paid perks or subscriptions attached to a contribution.": "支持完全自愿。捐助不附带付费权益，也不会开通订阅。",
    "Support with PayPal ↗": "通过PayPal支持 ↗",
    "PayPal contributions will open here once the project's payment link is connected.": "项目配置付款链接后，即可在此通过PayPal捐助。",
    "You will choose your amount and complete payment on PayPal. Vumiro never asks for your payment details.": "你将在PayPal上选择金额并完成付款。Vumiro绝不会索要你的支付信息。",
