    "Your profile, friends and settings sync automatically. Enable encrypted identity recovery in account settings to bring your contact identity to another device.": "你的个人资料、好友和设置会自动同步。若要在另一台设备上使用同一联系人身份，请在账户设置中启用加密身份恢复。",
    "This device has unbacked changes. Choose restore or back up in account settings to resolve them.": "此设备上有尚未备份的更改。请在账户设置中选择恢复或备份以解决。",
