    "Your profile, friends and settings were restored. This older backup has no recoverable contact identity. Enable encrypted identity recovery in account settings to bring the same contact identity to another device.": "你的个人资料、好友和设置已恢复。这份旧备份不包含可恢复的联系人身份。若要在另一台设备上使用同一联系人身份，请在账户设置中启用加密身份恢复。",
    "Account data is available from {when}. This device has unbacked changes. Choose restore or back up to resolve them.": "有{when}的账户数据可用。此设备上有尚未备份的更改。请选择恢复或备份以解决。",
