    "Enter your password": "Введите свой пароль",
    "Show password": "Показать пароль",
    "Use at least 12 characters.": "Используйте не менее 12 символов.",
    "Privacy notice and your rights": "Уведомление о конфиденциальности и ваши права",
    "Emanuel Queiroz (snoopeh) operates Vumiro's optional account service. Privacy requests and incident reports: snopeeh@gmail.com. We use your email to sign you in and restore your profile, friends, blocks, devices and preferences. Optional bios, profile backgrounds and manually entered provider links are shared directly with connected friends and included in your own account backup. Links are not verified integrations. Google or Microsoft shares your email and basic profile only when you choose an enabled sign-in option.": "Эмануэль Кейроз (snoopeh) управляет дополнительной службой учетных записей Vumiro. Запросы о конфиденциальности и отчеты об инцидентах: snopeeh@gmail.com. Мы используем вашу электронную почту, чтобы войти в систему и восстановить ваш профиль, друзей, блоки, устройства и настройки. Дополнительные биографии, фоны профилей и введенные вручную ссылки на провайдеров передаются непосредственно подключенным друзьям и включаются в резервную копию вашей собственной учетной записи. Ссылки не являются проверенными интеграциями. Google или Microsoft передают ваш адрес электронной почты и базовый профиль только тогда, когда вы выбираете включенный вариант входа.",
    "Supabase Auth is hosted in São Paulo, Brazil; Cloudflare D1 account storage is in Eastern North America; Brevo delivers account emails using EU-hosted infrastructure. Providers also process operational information internationally. Your signing identity is encrypted in the app before backup. Other synced fields are readable by authorized operators and providers. Screens, audio, chat, room passwords, raw private keys and recovery codes are not uploaded to the account service.": "Supabase Auth размещается в Сан-Паулу, Бразилия; Хранилище учетных записей Cloudflare D1 находится в восточной части Северной Америки; Brevo доставляет электронную почту, используя инфраструктуру, размещенную в ЕС. Провайдеры также обрабатывают оперативную информацию на международном уровне. Ваша подпись шифруется в приложении перед резервным копированием. Другие синхронизированные поля доступны для чтения авторизованным операторам и поставщикам. Экраны, аудио, чат, пароли комнат, необработанные закрытые ключи и коды восстановления не загружаются в службу учетных записей.",
    "You can export, correct or delete account data in settings; local device data remains. Separately, the connection directory retains identity-to-friend-tag and migration replay mappings without automatic expiry; deleting a Supabase account does not erase them. Hourly hashed IP allocation counters expire after their hourly window. Failed authentication-identity deletions remain pending for retry until completed. The full notice, version 2026-11-03, ships as PRIVACY.md (Windows) or licenses/PRIVACY.md (Linux) and explains retention, email processing and your rights. Never send passwords or recovery secrets to support.": "Вы можете экспортировать, исправить или удалить данные учетной записи в настройках; данные локального устройства остаются. Отдельно в каталоге подключения сохраняются сопоставления идентификатора с тегом друга и воспроизведения миграции без автоматического истечения срока действия; удаление учетной записи Supabase не стирает их. Счетчики почасового хеширования IP-адресов истекают после часового окна. Неудачное удаление удостоверения подлинности остается ожидающим повторной попытки до завершения. Полное уведомление, версия 2026-11-03, поставляется как PRIVACY.md (Windows) или licenses/PRIVACY.md (Linux) и объясняет хранение, обработку электронной почты и ваши права. Никогда не отправляйте пароли или секреты восстановления в службу поддержки.",
    "I reviewed the privacy notice": "Я ознакомился с уведомлением о конфиденциальности.",
