    "does not upload your device signing key": "не загружается ключ подписи вашего устройства",
    "Vumiro uploads only the client-encrypted identity envelope. It does not upload the raw signing key, identity recovery code, room passwords, screen, voice, or chat.": "Vumiro загружает только зашифрованный клиентом идентификационный конверт. Он не загружает необработанный ключ подписи, код восстановления личности, пароли комнаты, экран, голос или чат.",
    "Account data is not end-to-end encrypted": "Данные учетной записи не подвергаются сквозному шифрованию.",
    "The signing-identity envelope is encrypted in the client. Other synced account fields are readable to authorized Vumiro infrastructure operators and providers.": "Конверт подписывающей идентификации шифруется в клиенте. Другие поля синхронизированной учетной записи доступны для чтения авторизованным операторам и поставщикам инфраструктуры Vumiro.",
