    "Save your identity recovery code": "Сохраните код восстановления личности.",
    "Keep an offline copy. Vumiro cannot restore the same contact identity after a password reset without this code.": "Сохраните автономную копию. Без этого кода Vumiro не сможет восстановить ту же личность контакта после сброса пароля.",
