    "Waiting for the room owner. Trying again in {seconds} seconds…": "Ожидание владельца комнаты. Повторная попытка через {seconds} секунд…",
    "An account restores your profile, friends, blocks, stream preferences, and an encrypted signing identity on another device. Enabling recovery for an older profile changes its contact code; updated friends verify the signed transition automatically while older app versions may require a new friend acceptance.": "Учетная запись восстанавливает ваш профиль, друзей, блокировки, настройки потоковой передачи и зашифрованную подпись для подписи на другом устройстве. Включение восстановления старого профиля приводит к изменению его контактного кода; обновленные друзья автоматически проверяют подписанный переход, в то время как более старые версии приложения могут потребовать согласия нового друга.",
    "Profile backed up. High-resolution covers still stay on this device and share directly with updated friends; private cover backup is not enabled on the service yet.": "Резервная копия профиля сохранена. Обложки в высоком разрешении по-прежнему остаются на этом устройстве и делятся ими с обновленными друзьями напрямую; резервное копирование частного прикрытия еще не включено в сервисе.",
    "This device is backed up. Only the finished cover is backed up; the editable original stays on this device. Changes will sync automatically while Vumiro is open.": "Для этого устройства создана резервная копия. Резервируется только готовая обложка; редактируемый оригинал останется на этом устройстве. Изменения будут синхронизироваться автоматически, пока Vumiro открыт.",
    "Identity recovery is enabled. Save the recovery code before closing this panel. Your contact code changed; older friends may need to accept a new request.": "Восстановление личности включено. Сохраните код восстановления перед закрытием этой панели. Ваш контактный код изменился; старшим друзьям, возможно, придется принять новый запрос.",
    "0% mutes; 100% is original volume; up to 400% boosts quiet audio (may distort)": "0% отключения звука; 100% — исходный объем; до 400 % усиливает тихий звук (может искажаться)",
    "Friend request resolved; the blocked identity was not added.": "Запрос на добавление в друзья решен; заблокированная личность не была добавлена.",
    "Online. Named tags need the updated Vumiro service; your existing tag and contact code still work.": "Онлайн. Именованные теги нуждаются в обновленном сервисе Vumiro; ваш существующий тег и контактный код по-прежнему работают.",
    "Your username is saved. Shared usernames need the updated Vumiro service; use your existing tag or contact code for now.": "Ваше имя пользователя сохранено. Для общих имен пользователей требуется обновленный сервис Vumiro; на данный момент используйте существующий тег или контактный код.",
    "Service offline. Reconnecting automatically; you can also use Reconnect.": "Служба отключена. Автоматическое повторное подключение; вы также можете использовать Reconnect.",
    "display-capture; microphone; speaker-selection; autoplay; fullscreen": "захват изображения; микрофон; выбор докладчика; автозапуск; полноэкранный режим",
    "{p0}’s code is valid. Reconnect to send a request; they must also be online.": "Код пользователя {p0} действителен. Повторно подключитесь, чтобы отправить запрос; они также должны быть онлайн.\nКод",
