    "Speaker:": "Спикер:",
    "Vumiro — Sakura idle": "Вумиро — Сакура бездействует",
    "Fourteen small sakura petals descend slowly with gentle drift and rotation. Transparent, seamless 28-second vector loop. Reduced-motion preferences hide the effect.": "Четырнадцать маленьких лепестков сакуры медленно опускаются, плавно двигаясь и вращаясь. Прозрачный, бесшовный 28-секундный векторный цикл. Настройки ограниченного движения скрывают эффект.",
    "Vumiro — Blade reveal": "Вумиро — Раскрытие Клинка",
    "A curved red blade cut traces the actual opening in the V and reveals the mark in the center. The V glides left as the outlined Vumiro wordmark reveals and glides right. A brief camera push, roll and damped recoil emphasize the cut. The completed logo holds, then fades out. Duration 4.8 seconds.": "Изогнутый красный срез лезвия повторяет фактическое отверстие в форме буквы V и открывает знак в центре. Буква V скользит влево, когда появляется очерченный текстовый знак Вумиро, и скользит вправо. Короткий толчок камеры, вращение и смягченная отдача подчеркивают разрез. Готовый логотип держится, а затем исчезает. Продолжительность 4,8 секунды.",
    "Up to 720p": "До 720p",
    "Up to 1080p": "До 1080p",
    "Up to 1440p": "До 1440p",
    "Up to 2160p": "До 2160p",
    "(optional)": "(необязательно)",
    "YouTube profile link": "ссылка на профиль ютуб",
    "GitHub profile link": "Ссылка на профиль GitHub",
    "Chat messages": "Сообщения чата",
    "Visual alert for chat messages": "Визуальное оповещение о сообщениях чата",
    "Sound for chat messages": "Звук для сообщений в чате",
    "On Windows, notifications also appear as desktop popups when Vumiro is in the background.": "В Windows уведомления также отображаются в виде всплывающих окон на рабочем столе, когда Vumiro находится в фоновом режиме.",
    "A sample notification will appear in 3 seconds. Minimize Vumiro to test the desktop popup.": "Тестовое уведомление появится через 3 секунды. Сверните Vumiro, чтобы проверить уведомление на рабочем столе.",
    "This is your desktop notification preview.": "Это предварительный просмотр уведомления на рабочем столе.",
    "Friend connection closed before the nudge was acknowledged.": "Соединение с другом закрылось до подтверждения сигнала.",
    "Nudge cancelled because your connection changed.": "Сигнал отменён, поскольку ваше соединение изменилось.",
    "Nudge cancelled because your identity or friendship changed.": "Сигнал отменён, поскольку изменились ваша идентичность или статус дружбы.",
    "The nudge could not be sent. Try again later.": "Не удалось отправить сигнал. Повторите попытку позже.",
    "The nudge could not be signed. Try again later.": "Не удалось подписать сигнал. Повторите попытку позже.",
    "Nudges are available for online friends only.": "Сигналы доступны только для друзей в сети.",
    "Wait 30 seconds before nudging this friend again.": "Подождите 30 секунд, прежде чем снова отправить сигнал этому другу.",
    "Too many nudges. Try again in a moment.": "Слишком много сигналов. Повторите попытку немного позже.",
    "No nudge acknowledgment. Your friend may need a newer Vumiro version.": "Нет подтверждения сигнала. Возможно, вашему другу нужна более новая версия Vumiro.",
    "The friend connection could not start. Try again later.": "Не удалось установить соединение с другом. Повторите попытку позже.",
    "Your friend is not accepting nudges.": "Ваш друг не принимает сигналы.",
    "Nudge cancelled because your friend went offline.": "Сигнал отменён, поскольку друг вышел из сети.",
    "Test desktop popup in 3 seconds": "Проверить уведомление на рабочем столе через 3 секунды",
    "Nudge": "Сигнал",
