    "Allow nudges from friends": "Разрешить сигналы от друзей",
    "Silent mode": "Тихий режим",
    "Show a soft yellow glow instead of shaking. Reduced motion always uses the glow.": "Вместо тряски показывать мягкое жёлтое свечение. При уменьшении движения всегда используется свечение.",
    "Save nudge settings": "Сохранить настройки сигналов",
    "Nudge settings saved.": "Настройки сигналов сохранены.",
